```yaml
name: Publish Daily Repo Status

on:
  schedule:
    - cron: '0 0 * * *' # Runs daily at midnight UTC

permissions:
  contents: write

jobs:
  publish:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Generate daily repo status
        id: generate
        uses: actions/github-script@v6
        with:
          script: |
            const now = new Date();
            const twoDaysAgo = new Date(now.getTime() - 48 * 60 * 60 * 1000);

            // Fetch closed PRs (merged or not)
            const closedPRs = await github.paginate('GET /repos/{owner}/{repo}/pulls', {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'closed',
              sort: 'updated',
              direction: 'desc',
              per_page: 100
            });

            // Filter merged PRs in the last 48 hours
            const recentMerged = closedPRs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= twoDaysAgo);

            // Fetch open PRs
            const openPRs = await github.paginate('GET /repos/{owner}/{repo}/pulls', {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              per_page: 100
            });

            function formatPR(pr) {
              return `[#${pr.number}](https://github.com/${context.repo.owner}/${context.repo.repo}/pull/${pr.number}) | ${pr.title} | @${pr.user.login}`;
            }

            let content = `## ✅ Recently Merged (Last 48 Hours)\n\n| # | Title | Author |\n|---|-------|--------|\n`;
            recentMerged.forEach(pr => {
              content += `| ${formatPR(pr)} |\n`;
            });

            content += `\n## 🔄 Open Pull Requests (Needs Attention)\n\n| # | Title | Author |\n|---|-------|--------|\n`;
            openPRs.forEach(pr => {
              content += `| ${formatPR(pr)} |\n`;
            });

            // Write the markdown file
            const fs = require('fs');
            const path = '.github/daily-repo-status.md';
            fs.writeFileSync(path, content);
            core.setOutput('file', path);

      - name: Commit and push changes
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git add .github/daily-repo-status.md
          if git diff --cached --quiet; then
            echo "No changes to commit."
          else
            git commit -m "Update daily repo status"
            git push
          fi
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
```

